window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9834f1f56ca4f0d5"]={"versions": [{"id": "FIG-9834f1f56ca4f0d5", "releases": ["R2.1.20", "R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Modellansicht (Subsystem-Modellierung) im Rahmen des AUTOSAR-Simulink-Styleguides. Das Diagramm demonstriert die Modellierung und Kennzeichnung einer AUTOSAR-Runnable-Entity (<code>Runnable_INSIDE_EA</code>), die vollständig innerhalb einer Exclusive Area ausgeführt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Modell-Fenster / Subsystem:</strong> <code>AUTOSAR_Exclusive_Areas/Runnable_INSIDE_EA</code>.\n</li><li><strong>Ereignis-Trigger:</strong> <code>RteEvent</code> (Simulink Function-Call-Trigger-Port <code>f()</code>).\n</li><li><strong>Tag / Konfiguration:</strong> Block <code>Exclusive Area ID=SMS</code>.\n</li><li><strong>Eingangsschnittstellen (Inports):</strong>\n<ul class=\"fig-list\"><li>Inport 1: <code>DE_1</code>\n</li><li>Inport 2: <code>DE_5</code>\n</li></ul>\n</li><li><strong>Ausgangsschnittstellen (Outports):</strong>\n<ul class=\"fig-list\"><li>Outport 1: <code>DE_a</code>\n</li><li>Outport 2: <code>DE_e</code>\n</li><li>Outport 3: <code>IRV</code> (Inter-Runnable Variable)\n</li></ul>\n</li><li><strong>Funktionale Blöcke:</strong>\n<ul class=\"fig-list\"><li>Summenblock (<code>+-</code>), Diskrete Differenz (<code>Difference</code>, <code>(z-1)/z</code>) mit Rückkopplungsschleife auf den Summenblock.\n</li><li>Vorzeichenfunktion (<code>Sign</code>).\n</li><li>Verstärkungsfaktor (<code>Gain</code>, Faktor 2).\n</li></ul>\n</li><li><strong>Textuelle Annotationen:</strong> Modellierungsnotiz mit Verweis auf das AUTOSAR-Metamodell-Attribut <code>INSIDE-EXCLUSIVE-AREAS</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Runnable wird durch das konfigurierte <code>RteEvent</code> (Function-Call-Trigger) aufgerufen.\n</li><li>Der gesamte Berechnungsablauf der Runnable erfolgt innerhalb der definierten Exclusive Area (<code>SMS</code>).\n</li><li>Die Eingangssignale <code>DE_1</code> und <code>DE_5</code> werden verarbeitet:\n<ul class=\"fig-list\"><li><code>DE_1</code> wird mit dem rückgekoppelten Differenzwert verrechnet, durchläuft den Differenzblock und wird an Outport <code>DE_a</code> bereitgestellt.\n</li><li><code>DE_5</code> wird verzweigt und parallel über den <code>Sign</code>-Block an <code>DE_e</code> sowie über den <code>Gain</code>-Block an den Inter-Runnable-Ausgang <code>IRV</code> übergeben.\n</li></ul>\n</li><li>Alle Signaloperationen und internen Zustandsaktualisierungen finden geschützt vor nebenläufigen Zugriffen statt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Wenn eine Runnable vollständig innerhalb einer Exclusive Area liegt, wird das Subsystem der obersten Ebene als Exclusive Area getaggt (<code>Exclusive Area ID=SMS</code>).\n</li><li>Die Modell-Annotation legt fest:\n<ul class=\"fig-list\"><li>Im AUTOSAR-Software-Component-Description-Metamodell wird die Eigenschaft <code>INSIDE-EXCLUSIVE-AREAS</code> gesetzt.\n</li><li>Die Code-Generierung für die Runnable selbst wird durch dieses Tagging nicht beeinflusst (keine expliziten RTE-Schutzaufrufe innerhalb des generierten Runnable-Funktionsrumpfs erforderlich, da der Schutz auf Task- bzw. Scheduler-Ebene gewährleistet wird).\n</li></ul>\n</li></ul>"}, {"id": "FIG-133cf7913700d504", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Simulink-Modellansicht (Subsystem-Modellierung) im Rahmen des AUTOSAR-Simulink-Styleguides. Das Diagramm demonstriert die Modellierung und Kennzeichnung einer AUTOSAR-Runnable-Entity (<code>Runnable_INSIDE_EA</code>), die vollständig innerhalb einer Exclusive Area ausgeführt wird.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Modell-Fenster / Subsystem:</strong> <code>AUTOSAR_Exclusive_Areas/Runnable_INSIDE_EA</code>.\n</li><li><strong>Ereignis-Trigger:</strong> <code>RteEvent</code> (Simulink Function-Call-Trigger-Port <code>f()</code>).\n</li><li><strong>Tag / Konfiguration:</strong> Block <code>Exclusive Area ID=SMS</code>.\n</li><li><strong>Eingangsschnittstellen (Inports):</strong>\n<ul class=\"fig-list\"><li>Inport 1: <code>DE_1</code>\n</li><li>Inport 2: <code>DE_5</code>\n</li></ul>\n</li><li><strong>Ausgangsschnittstellen (Outports):</strong>\n<ul class=\"fig-list\"><li>Outport 1: <code>DE_a</code>\n</li><li>Outport 2: <code>DE_e</code>\n</li><li>Outport 3: <code>IRV</code> (Inter-Runnable Variable)\n</li></ul>\n</li><li><strong>Funktionale Blöcke:</strong>\n<ul class=\"fig-list\"><li>Summenblock (<code>+-</code>), Diskrete Differenz (<code>Difference</code>, <code>(z-1)/z</code>) mit Rückkopplungsschleife auf den Summenblock.\n</li><li>Vorzeichenfunktion (<code>Sign</code>).\n</li><li>Verstärkungsfaktor (<code>Gain</code>, Faktor 2).\n</li></ul>\n</li><li><strong>Textuelle Annotationen:</strong> Modellierungsnotiz mit Verweis auf das AUTOSAR-Metamodell-Attribut <code>INSIDE-EXCLUSIVE-AREAS</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Runnable wird durch das konfigurierte <code>RteEvent</code> (Function-Call-Trigger) aufgerufen.\n</li><li>Der gesamte Berechnungsablauf der Runnable erfolgt innerhalb der definierten Exclusive Area (<code>SMS</code>).\n</li><li>Die Eingangssignale <code>DE_1</code> und <code>DE_5</code> werden verarbeitet:\n<ul class=\"fig-list\"><li><code>DE_1</code> wird mit dem rückgekoppelten Differenzwert verrechnet, durchläuft den Differenzblock und wird an Outport <code>DE_a</code> bereitgestellt.\n</li><li><code>DE_5</code> wird verzweigt und parallel über den <code>Sign</code>-Block an <code>DE_e</code> sowie über den <code>Gain</code>-Block an den Inter-Runnable-Ausgang <code>IRV</code> übergeben.\n</li></ul>\n</li><li>Alle Signaloperationen und internen Zustandsaktualisierungen finden geschützt vor nebenläufigen Zugriffen statt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Wenn eine Runnable vollständig innerhalb einer Exclusive Area liegt, wird das Subsystem der obersten Ebene als Exclusive Area getaggt (<code>Exclusive Area ID=SMS</code>).\n</li><li>Die Modell-Annotation legt fest:\n<ul class=\"fig-list\"><li>Im AUTOSAR-Software-Component-Description-Metamodell wird die Eigenschaft <code>INSIDE-EXCLUSIVE-AREAS</code> gesetzt.\n</li><li>Die Code-Generierung für die Runnable selbst wird durch dieses Tagging nicht beeinflusst (keine expliziten RTE-Schutzaufrufe innerhalb des generierten Runnable-Funktionsrumpfs erforderlich, da der Schutz auf Task- bzw. Scheduler-Ebene gewährleistet wird).\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-9834f1f56ca4f0d5", "to": "FIG-133cf7913700d504", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
